    // ● constructor
    /**
     * Creates a tab page.
     * @param {tp.CreateParams|object|HTMLElement|string} CreateParams The tab page create parameters, handle, or selector.
     */
    constructor(CreateParams) {
        super(CreateParams);
    }

    // ● protected
    /**
     * Notification called after handle creation.
     * @returns {void}
     */
