        if (this.fTextBox instanceof HTMLInputElement && tp.IsFunction(this.fTextBox.setRangeText)) {
            this.fTextBox.setRangeText(Text, this.fTextBox.selectionStart, this.fTextBox.selectionEnd, "end");
        }
