    set Url(Value) {
        if (this.Handle instanceof HTMLElement) {
            Value = tp.IsNil(Value) ? "" : String(Value);
            this.Handle.style.backgroundImage = tp.IsBlank(Value) ? "" : "url(\"" + Value + "\")";
        }
    }
